    for where, row in files:
        if row["state"] not in FILE_STATES:
            report.add(where, "file-accounting", f"`state` must be one of {list(FILE_STATES)}")
        if row["state"] == "ignored":
            read_line(report, where, row, "reason")
        if row["path"] in states:
